// @vitest-environment jsdom
// #796 (MVP IV F3): the homepage links to the study page as "The numbers". The page is a static file outside
// the SPA (client/public/study.html, generated by `npm run study`), so the link is a plain <a>, not a router Link.
import { existsSync, readFileSync } from 'node:fs';
import { MemoryRouter, useLocation } from 'react-router-dom';
import { afterEach, beforeEach, describe, expect, it, vi, type MockInstance } from 'vitest';
import Landing, { STUDY_HREF, STUDY_LABEL, WATCH_LABEL } from '../../client/src/pages/Landing';
import type { NycSummary } from '../../client/src/pages/landingModel';
import { link, mount, tabOrder, textOf } from './kitDom';

const ready: NycSummary = {
  status: 'ready', businesses: 18, commuters: 60, matched: 24, requested: 24,
  businessIds: ['biz-a', 'biz-b'], employeeIds: ['emp-a', 'emp-b'], watchPackageId: 'shp-3',
};
const STATES: NycSummary[] = [ready, { status: 'loading' }, { status: 'error' }, { status: 'unavailable' }];

let error: MockInstance;
let warn: MockInstance;
beforeEach(() => {
  window.localStorage.clear();
  error = vi.spyOn(console, 'error').mockImplementation(() => {});
  warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
});
afterEach(() => { vi.restoreAllMocks(); });

const logged = () => [...error.mock.calls, ...warn.mock.calls].map((args) => args.map(String).join(' '));

function Where() {
  const { pathname } = useLocation();
  return <output data-testid="where">{pathname}</output>;
}

describe('the homepage links to the study page as "The numbers" (#796)', () => {
  it('shows one link with the text "The numbers" and href /study.html', () => {
    expect(STUDY_LABEL).toBe('The numbers');
    expect(STUDY_HREF).toBe('/study.html');
    const { container } = mount(<MemoryRouter><Landing initialSummary={ready} /></MemoryRouter>);
    const a = link(container, 'The numbers'); // throws unless there is exactly one
    expect(a.getAttribute('href')).toBe('/study.html');
    expect(a.getAttribute('target')).toBeNull(); // same tab: the study page links back to /
    expect(logged()).toEqual([]);
  });

  it('is there in every state of the summary: ready, loading, failed and travel data missing', () => {
    for (const s of STATES) {
      const m = mount(<MemoryRouter><Landing initialSummary={s} /></MemoryRouter>);
      expect(link(m.container, 'The numbers').getAttribute('href'), s.status).toBe('/study.html');
      m.unmount();
    }
    expect(logged()).toEqual([]);
  });

  it('is a plain <a>: a click is left to the browser and the router stays on /', () => {
    const { container } = mount(<MemoryRouter><Landing initialSummary={ready} /><Where /></MemoryRouter>);
    const a = link(container, 'The numbers');
    // A router Link calls preventDefault and navigates in the SPA. Read the flag after React's handlers
    // (they run on the root container, before <body>), then cancel so jsdom does not try to load the page.
    let prevented: boolean | null = null;
    const seen = (e: Event) => { prevented = e.defaultPrevented; e.preventDefault(); };
    document.body.addEventListener('click', seen);
    a.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, button: 0 }));
    document.body.removeEventListener('click', seen);
    expect(prevented).toBe(false);
    expect(textOf(container.querySelector('[data-testid="where"]')!)).toBe('/');
    expect(logged()).toEqual([]);
  });

  it('sits with the secondary links: under Business and Employee, above the stats line the page still ends with', () => {
    const { container } = mount(<MemoryRouter><Landing initialSummary={ready} /></MemoryRouter>);
    const a = link(container, 'The numbers');
    const page = container.querySelector('.landing')!;
    expect([...page.children].map((el) => el.className)).toEqual(['landing-intro', 'workspaces', 'landing-more', 'op-summary']);
    expect(a.parentElement!.className).toBe('landing-more');
    // not inside the intro (the button's block), the entries list or the stats section
    expect(a.closest('.landing-intro, .workspaces, .op-summary')).toBeNull();
    expect(tabOrder(container).map(textOf)).toEqual([
      WATCH_LABEL, 'BusinessSend a package and track it→', 'EmployeeSet a commute and see your deliveries→', 'The numbers',
    ]);
  });
});

describe('the link target and its style (#796)', () => {
  it('points at a file that is committed in client/public and links back to /', () => {
    expect(existsSync('client/public/study.html')).toBe(true);
    expect(readFileSync('client/public/study.html', 'utf8')).toMatch(/<a [^>]*href="\/"/);
  });

  it('is styled with the existing tokens: accent colour, underlined, a visible focus ring, no fixed size', () => {
    const css = readFileSync('client/src/styles/landing.css', 'utf8').replace(/\/\*[\s\S]*?\*\//g, '');
    const rule = (selector: string) => new RegExp(`${selector.replace(/[.:]/g, '\\$&')} \\{([^}]*)\\}`).exec(css)![1];
    expect(rule('.landing-more-link')).toMatch(/color: var\(--accent, #1D5075\)/);
    expect(rule('.landing-more-link')).toMatch(/text-decoration: underline/);
    expect(rule('.landing-more-link:focus-visible')).toMatch(/outline: 2px solid var\(--accent, #1D5075\)/);
    expect(rule('.landing-more')).toMatch(/font-size: var\(--text-sm, 13px\)/);
    expect(rule('.landing-more') + rule('.landing-more-link')).not.toMatch(/(width|height|white-space)/);
  });
});
